mapper.select:
select ifnull(sum(case when status = 5 then pay_amount else 0 end), 0) as revenue, ifnull(sum(case when status = 5 then goods_amount else 0 end), 0) as goodsRevenue, ifnull(sum(case when status = 5 then delivery_fee else 0 end), 0) as deliveryRevenue,
ifnull(sum(case when refund_status = 2 then pay_amount else 0 end), 0) as refundedAmount,
ifnull(sum(case when status = 5 and refund_status = 2 then pay_amount else 0 end), 0) as refundedInRevenue,
ifnull(sum(case when refund_status = 1 then pay_amount else 0 end), 0) as refundingAmount, count(case when status = 5 then 1 end) as orderCount, count(case when status = 6 then 1 end) as cancelledCount, count(case when refund_status = 2 then 1 end) as refundedCount from biz_order where create_time >= #{start} and create_time < #{end}
and delivery_type = #{deliveryType}

select date_format(create_time, '%Y-%m-%d') as timeLabel, ifnull(sum(case when status = 5 then pay_amount else 0 end), 0) as revenue, count(case when status = 5 then 1 end) as orderCount, count(case when refund_status = 2 then 1 end) as refundedCount from biz_order where create_time >= #{start} and create_time < #{end}
and delivery_type = #{deliveryType}
group by date_format(create_time, '%Y-%m-%d') order by timeLabel asc

select date_format(create_time, '%Y-%m-%d %H:00') as timeLabel, ifnull(sum(case when status = 5 then pay_amount else 0 end), 0) as revenue, count(case when status = 5 then 1 end) as orderCount, count(case when refund_status = 2 then 1 end) as refundedCount from biz_order where create_time >= #{start} and create_time < #{end}
and delivery_type = #{deliveryType}
group by date_format(create_time, '%Y-%m-%d %H:00') order by timeLabel asc

select i.goods_id as goodsId, max(i.goods_name) as goodsName, sum(i.quantity) as quantity, ifnull(sum(i.subtotal), 0) as amount from biz_order_item i inner join biz_order o on o.id = i.order_id where o.status = 5 and o.refund_status != 2 and o.create_time >= #{start} and o.create_time < #{end}
and o.delivery_type = #{deliveryType}
group by i.goods_id order by
amount desc quantity desc
, i.goods_id asc limit #{topN}

select c.id as categoryId, ifnull(c.name, '未分类') as categoryName, ifnull(sum(i.subtotal), 0) as amount, sum(i.quantity) as quantity from biz_order_item i inner join biz_order o on o.id = i.order_id left join biz_goods g on g.id = i.goods_id left join biz_category c on c.id = g.category_id where o.status = 5 and o.refund_status != 2 and o.create_time >= #{start} and o.create_time < #{end}
and o.delivery_type = #{deliveryType}
group by c.id, c.name order by amount desc

select i.goods_id as goodsId, sum(i.quantity) as refundCount from biz_order_item i inner join biz_order o on o.id = i.order_id where o.refund_status = 2 and o.create_time >= #{start} and o.create_time < #{end}
and o.delivery_type = #{deliveryType}
group by i.goods_id

select hour(create_time) as hour, count(*) as orderCount, ifnull(sum(pay_amount), 0) as revenue from biz_order where status = 5 and create_time >= #{start} and create_time < #{end}
and delivery_type = #{deliveryType}
group by hour(create_time) order by hour asc
